// ---- Internal state ----
static bool sEnabled = OLED_ENABLED_DEFAULT;
static uint8_t sAddr = 0;
static bool sInitialized = false;

static Adafruit_SSD1306 sDisplay(OLED_SCREEN_WIDTH, OLED_SCREEN_HEIGHT, &Wire, -1);

static ExoState sState = EXO_READY;
static ExoState sLastPainted = static_cast<ExoState>(0xFF);
static uint32_t sNextAllowedMs = 0;
static uint32_t sStartupCompleteMs = 0;

// ---- Helpers ----
static bool i2cPresent(uint8_t addr) {
  Wire.beginTransmission(addr);
  return (Wire.endTransmission() == 0);
}

static uint8_t detectOledAddr() {
  // Try primary address first (0x3C for 128x32, 0x3D for 128x64)
  if (i2cPresent(OLED_I2C_ADDR_PRIMARY)) return OLED_I2C_ADDR_PRIMARY;
  if (i2cPresent(OLED_I2C_ADDR_ALT))     return OLED_I2C_ADDR_ALT;
  return 0;
}

const __FlashStringHelper* oledGetStateText(ExoState s) {
  switch (s) {
    case EXO_READY:         return F("READY");
    case EXO_INDEX_PINCH:   return F("INDEX PINCH");
    case EXO_MIDDLE_PINCH:  return F("MIDDLE PINCH");
    case EXO_RING_PINCH:    return F("RING PINCH");
    case EXO_KEYGRIP_OPEN:  return F("KEYGRIP OPEN");
    case EXO_KEYGRIP_CLOSE: return F("KEYGRIP CLOSE");
    case EXO_GRASP_OPEN:    return F("-- REST --");
    case EXO_GRASP_CLOSE:   return F("GRASP CLOSE");
    case EXO_THUMB_FLEX:    return F("THUMB FLEX");
    case EXO_THUMB_EXTEND:  return F("THUMB EXT");
    case EXO_THUMB_REST:    return F("THUMB REST");
    case EXO_INDEX_FLEX:    return F("INDEX FLEX");
    case EXO_INDEX_EXTEND:  return F("INDEX EXT");
    case EXO_INDEX_REST:    return F("INDEX REST");
    case EXO_MIDDLE_FLEX:   return F("MID FLEX");
    case EXO_MIDDLE_EXTEND: return F("MID EXT");
    case EXO_MIDDLE_REST:   return F("MID REST");
    case EXO_RING_FLEX:     return F("RING FLEX");
    case EXO_RING_EXTEND:   return F("RING EXT");
    case EXO_RING_REST:     return F("RING REST");
    case EXO_PINKY_FLEX:    return F("PINKY FLEX");
    case EXO_PINKY_EXTEND:  return F("PINKY EXT");
    case EXO_PINKY_REST:    return F("PINKY REST");
    case EXO_WRIST_FLEX:    return F("WRIST FLEX");
    case EXO_WRIST_EXTEND:  return F("WRIST EXT");
    case EXO_WRIST_REST:    return F("WRIST REST");
    case EXO_RAD_FLEX:      return F("RAD FLEX");
    case EXO_RAD_EXTEND:    return F("RAD EXT");
    case EXO_RAD_REST:      return F("RAD REST");
    default:                return F("UNKNOWN");
  }
}

// Draw text optimized for 128x64 SSD1306 display
static void oledDisplayText(const String& text) {
  sDisplay.clearDisplay();
  sDisplay.setTextSize(2);  // 2x scale fits better on 128x64
  sDisplay.setTextColor(SSD1306_WHITE);
  sDisplay.setFont(NULL);   // Use default font
  
  // Split text and center vertically
  int16_t x1, y1;
  uint16_t w, h;
  sDisplay.getTextBounds(text, 0, 0, &x1, &y1, &w, &h);
  
  int16_t x = (OLED_SCREEN_WIDTH - (int)w) / 2;
  int16_t y = (OLED_SCREEN_HEIGHT - (int)h) / 2;
  if (x < 0) x = 0;
  if (y < 0) y = 0;
  
  sDisplay.setCursor(x, y);
  sDisplay.println(text);
  sDisplay.display();
}

// ---- Public API ----
bool oledInit() {
  if (!sEnabled) return false;

  // Initialize I2C
  Wire.begin();
  Wire.setClock(400000);

  // Detect OLED address with timeout
  const uint32_t detectStart = millis();
  sAddr = detectOledAddr();
  
  if (sAddr == 0) {
    // Device not found on I2C bus
    sEnabled = false;
    return false;
  }

  // Initialize display with timeout protection
  const uint32_t t0 = millis();
  const uint32_t MAX_INIT_MS = 200;  // Increased timeout for robustness
  
  if (!sDisplay.begin(SSD1306_SWITCHCAPVCC, sAddr)) {
    sEnabled = false;
    return false;
  }

  // Check if initialization took too long
  if ((millis() - t0) > MAX_INIT_MS) {
    sEnabled = false;
    return false;
  }

  // Configure display for 128x64 full-screen text
  sDisplay.clearDisplay();
  sDisplay.setTextSize(2);        // 2x text size for readability
  sDisplay.setTextColor(SSD1306_WHITE);
  sDisplay.setFont(NULL);         // Use default monospace font
  sDisplay.cp437(true);           // Use full 256 char 'Code Page 437' font
  sDisplay.display();

  sInitialized = true;
  sLastPainted = static_cast<ExoState>(0xFF);  // Force first paint
  sNextAllowedMs = 0;
  sStartupCompleteMs = 0;
  
  return true;
}

void oledSetEnabled(bool enabled) {
  if (enabled == sEnabled) return;
  sEnabled = enabled;
  if (sEnabled) {
    if (!oledInit()) {
      sEnabled = false;
    }
  }
}

bool oledEnabled() {
  return sEnabled && sInitialized;
}

void oledSetState(ExoState s) {
  sState = s;
  // Only paint after startup sequence completes
  if (millis() < sStartupCompleteMs) {
    return;  // Still in startup animation
  }
}

ExoState oledGetState() {
  return sState;
}

void oledStartupAnimation() {
  if (!sEnabled || !sInitialized) return;

  const uint32_t animDuration = 2500;  // 2.5 seconds of animation
  const uint32_t holdReadyDuration = 800;  // Hold "READY" for 0.8 seconds
  const uint32_t totalStartup = animDuration + holdReadyDuration;

  const uint32_t startTime = millis();
  uint32_t elapsed = 0;
  uint8_t frameIndex = 0;
  const uint8_t frameCount = sizeof(brainFrames) / sizeof(brainFrames[0]);

  // Play animation frames for animDuration
  while (elapsed < totalStartup) {
    elapsed = millis() - startTime;

    if (elapsed < animDuration) {
      // Show brain animation frames
      frameIndex = (elapsed / BRAIN_FRAME_DELAY_MS) % frameCount;
      sDisplay.clearDisplay();
      
      // Center the 64x64 brain animation on 128x64 display
      int offsetX = (OLED_SCREEN_WIDTH - BRAIN_FRAME_WIDTH) / 2;
      int offsetY = (OLED_SCREEN_HEIGHT - BRAIN_FRAME_HEIGHT) / 2;
      
      sDisplay.drawBitmap(offsetX, offsetY, brainFrames[frameIndex], 
                          BRAIN_FRAME_WIDTH, BRAIN_FRAME_HEIGHT, SSD1306_WHITE);
      sDisplay.display();
    } else {
      // Show "READY" message after animation
      oledDisplayText(String(oledGetStateText(EXO_READY)));
    }

    delay(BRAIN_FRAME_DELAY_MS);
  }

  sStartupCompleteMs = millis();
  sLastPainted = static_cast<ExoState>(0xFF);  // Force paint of new state
}

void oledTick() {
  if (!sEnabled || !sInitialized) return;
  
  // Skip updates during startup animation
  if (millis() < sStartupCompleteMs) return;

  const uint32_t now = millis();
  if (now < sNextAllowedMs) return;

  if (sState != sLastPainted) {
    // Render new state with appropriately sized text
    String txt = String(oledGetStateText(sState));
    oledDisplayText(txt);
    sLastPainted = sState;
  }

  sNextAllowedMs = now + OLED_UPDATE_PERIOD_MS;
}
